import Foundation

/// 静态补全脚本渲染（fish / PowerShell）。
///
/// ConsoleKit 只原生渲染 bash / zsh；这两个 shell 由本文件按同一份
/// `capabilityList()` 生成，因此命令/选项变化时不会与命令面漂移
/// （对齐规范 `docs/spec/cli-surface.md` §9 与 Python 侧的 `completion`）。
enum CompletionScripts {
    static func fish(_ capabilities: [CommandCapability]) -> String {
        var lines = [
            "# orzmc fish completion (generated by `orzmc completion fish`)",
            "complete -c orzmc -f",
        ]
        for capability in capabilities {
            lines.append(
                "complete -c orzmc -n \"__fish_use_subcommand\" -a \"\(capability.name)\" -d \"\(escape(capability.help))\""
            )
            for value in capability.values where value.kind != "argument" {
                var parts = ["complete", "-c", "orzmc", "-n", "\"__fish_seen_subcommand_from \(capability.name)\""]
                for name in value.names {
                    if name.hasPrefix("--") {
                        parts += ["-l", String(name.dropFirst(2))]
                    } else if name.hasPrefix("-") {
                        parts += ["-s", String(name.dropFirst())]
                    }
                }
                // 需要取值的选项加 `-r`；flag 不加。
                if !value.flag { parts.append("-r") }
                if !value.help.isEmpty { parts += ["-d", "\"\(escape(value.help))\""] }
                lines.append(parts.joined(separator: " "))
            }
        }
        return lines.joined(separator: "\n") + "\n"
    }

    static func powershell(_ capabilities: [CommandCapability]) -> String {
        let commandList = capabilities.map { "'\($0.name)'" }.joined(separator: ", ")
        return """
        # orzmc PowerShell completion (generated by `orzmc completion powershell`)
        Register-ArgumentCompleter -Native -CommandName orzmc -ScriptBlock {
            param($wordToComplete, $commandAst, $cursorPosition)
            $commands = @(\(commandList))
            $commands | Where-Object { $_ -like "$wordToComplete*" } | ForEach-Object {
                [System.Management.Automation.CompletionResult]::new($_, $_, 'ParameterValue', $_)
            }
        }

        """
    }

    /// 转义进双引号字符串（fish 的 `-d` 与 PowerShell 注释外的文本）。
    private static func escape(_ text: String) -> String {
        text
            .replacingOccurrences(of: "\\", with: "\\\\")
            .replacingOccurrences(of: "\"", with: "\\\"")
            .replacingOccurrences(of: "$", with: "\\$")
    }
}
